/* Ironlog — the AI key and calls to Anthropic: models per feature, the monthly
   cap and usage, one call, a JSON reply, error words. Split out of tools.js
   (ROADMAP E17 phase 5) so voice logging, the coach and import can use it
   without the Tools sheet. The key stays on this phone. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, esc, today } from './core.js';
import { save } from './database.js';
import { confirmDlg } from './kit.js';
import { S } from './state.js';
/* end imports */

/* ---------------- AI ---------------- */
/* $ per million tokens, input / output. One place to update.
   Haiku's price is for prompts up to 100K tokens; every Ironlog call is far
   under that. Prices from platform.claude.com/docs/en/about-claude/pricing,
   checked 2026-11-05. */
const AI_MODELS = {
  'claude-haiku-5-5': { name: 'Claude Haiku 5.5', short: 'Haiku', in: 0.10, out: 0.50 },
  'claude-sonnet-5-5': { name: 'Claude Sonnet 5.5', short: 'Sonnet', in: 2, out: 10 },
  'claude-opus-5-5': { name: 'Claude Opus 5.5', short: 'Opus', in: 4, out: 20 },
};
export const AI_MODEL = 'claude-haiku-5-5';   // the default for every feature
/* Each feature can use its own model (Settings → AI). Haiku unless chosen. */
function aiModelFor(feature) { const m = (S.settings.aiModels || {})[feature]; return AI_MODELS[m] ? m : AI_MODEL; }
/* Every AI feature, with a typical call's tokens for the cost hint. */
const AI_FEATURES = [
  { id: 'voice', name: 'Voice logging, hard sentences', what: 'Reads a spoken set when the on-device grammar can\'t', tokIn: 450, tokOut: 40, per: 'set' },
  { id: 'plan', name: 'Plan writer', what: 'Turns your own plan, in any format, into an Ironlog plan', tokIn: 4500, tokOut: 2500, per: 'plan' },
  { id: 'tailor', name: 'Tailor it', what: 'Claude fits a coach-built plan to your log — swaps and set changes you approve', tokIn: 3500, tokOut: 400, per: 'plan' },
  { id: 'ask', name: 'Coach, odd questions', what: 'Only for typed questions the coach can\'t answer on its own', tokIn: 700, tokOut: 180, per: 'question' },
];
const AI_CAP_DEFAULT = 1;
export function aiCap() { const c = S.settings.aiCap; return c == null || isNaN(+c) ? AI_CAP_DEFAULT : Math.max(0, +c); }
const aiMonth = () => today().slice(0, 7);
export function aiUsage() {
  let u = null;
  try { u = JSON.parse(localStorage.getItem('ironlog.aiUsage') || 'null'); } catch (e) { /* blocked or bad JSON */ }
  return u && u.month === aiMonth() ? u : { month: aiMonth(), calls: 0, inTok: 0, outTok: 0, usd: 0, by: {} };
}
function aiSaveUsage(u) { try { localStorage.setItem('ironlog.aiUsage', JSON.stringify(u)); } catch (e) { /* the cap can't hold without storage; calls still work */ } }
export function aiPrice(model, inTok, outTok) { const m = AI_MODELS[model] || AI_MODELS[AI_MODEL]; return (inTok * m.in + outTok * m.out) / 1e6; }
function aiRecord(feature, model, inTok, outTok) {
  const u = aiUsage(), usd = aiPrice(model, inTok, outTok);
  const f = u.by[feature] = u.by[feature] || { calls: 0, inTok: 0, outTok: 0, usd: 0 };
  [u, f].forEach(o => { o.calls++; o.inTok += inTok; o.outTok += outTok; o.usd += usd; });
  aiSaveUsage(u);
}
function aiCapped() { return aiUsage().usd >= aiCap(); }
/* What a feature can do right now: 'on', 'nokey' or 'capped'. */
export function aiStatus() { return !aiKey() ? 'nokey' : aiCapped() ? 'capped' : 'on'; }
function aiCostHint(F) {
  const one = aiPrice(aiModelFor(F.id), F.tokIn, F.tokOut);
  return `about $${one < 0.001 ? one.toFixed(5) : one.toFixed(4)} a ${F.per} — ${Math.floor(1 / one).toLocaleString()} for $1`;
}
export function usd(v) { return `$${v < 0.01 && v > 0 ? v.toFixed(4) : v.toFixed(2)}`; }
/* The one door to the API. Throws with .nokey, .capped, .status or .net set,
   so each feature can fall back to its local path and say why. */
export async function aiCall({ feature, system, user, maxTokens = 1024 }) {
  const key = aiKey(), model = aiModelFor(feature);
  if (!key) { const e = new Error('nokey'); e.nokey = true; throw e; }
  if (aiCapped()) { const e = new Error('capped'); e.capped = true; throw e; }
  let r;
  try {
    r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true',
      },
      body: JSON.stringify({
        model,
        max_tokens: maxTokens,
        thinking: { type: 'disabled' },   // short structured jobs: no reasoning to pay for
        ...(system ? { system } : {}),
        messages: [{ role: 'user', content: user }],
      }),
    });
  } catch (e) { const err = new Error('network'); err.net = true; throw err; }
  if (!r.ok) {
    const body = await r.text().catch(() => '');
    let msg = '';
    try { msg = JSON.parse(body).error.message; } catch (e) { msg = body.slice(0, 160); }
    const err = new Error(msg || ('HTTP ' + r.status));
    err.status = r.status; err.body = 'upstream ' + r.status + ' ' + body;
    throw err;
  }
  const data = await r.json();
  const u = data.usage || {};
  aiRecord(feature, AI_MODELS[data.model] ? data.model : model, u.input_tokens || 0, u.output_tokens || 0);
  return { text: (data.content || []).filter(b => b.type === 'text').map(b => b.text).join(''), stop: data.stop_reason, usage: u };
}
/* Why a call didn't happen, in words for a toast. */
export function aiWhy(e) {
  if (e.nokey) return 'No AI key — add one in Settings → AI';
  if (e.capped) return `This month's AI cap (${usd(aiCap())}) is reached — raise it in Settings → AI`;
  if (e.net) return 'Couldn\'t reach Anthropic — offline?';
  if (e.status === 401) return 'The AI key was refused — check it in Settings → AI';
  if (e.status === 429) return 'Anthropic is rate-limiting this key — try again shortly';
  if (e.status === 400 && /credit/i.test(e.message)) return 'The Anthropic account is out of credit';
  return `AI call failed — ${e.message || e.status}`;
}
/* Settings: this month's spend and each feature's state. */
export function aiUsageHtml() {
  const u = aiUsage(), cap = aiCap(), st = aiStatus();
  const word = { on: 'On', nokey: 'Needs a key', capped: 'Paused — cap reached' };
  return `<div class="card tight" style="margin-bottom:10px">
    <div class="row between"><span class="eyebrow">This month</span>${u.calls ? '<button class="btn xs ghost" id="stAiReset">Reset count</button>' : ''}</div>
    <div class="sub" style="margin:4px 0 6px">${u.calls ? `${u.calls} call${u.calls === 1 ? '' : 's'} · ${u.inTok.toLocaleString()} tokens in, ${u.outTok.toLocaleString()} out · about <b>${usd(u.usd)}</b> of ${usd(cap)}` : `No AI calls yet · cap ${usd(cap)}`}</div>
    <div class="fitbar${st === 'capped' ? ' lag' : ''}" role="img" aria-label="${Math.min(100, cap ? u.usd / cap * 100 : 100).toFixed(0)}% of the cap used"><i style="width:${Math.min(100, cap ? u.usd / cap * 100 : 100).toFixed(1)}%"></i></div>
    ${AI_FEATURES.map(F => `<div class="row between" style="margin-top:8px;gap:8px"><div class="grow"><b style="font-size:13px">${esc(F.name)}</b>
      <div class="sub">${esc(F.what)} · ${esc(aiCostHint(F))}</div>
      <select class="aimodel" data-aimodel="${F.id}" aria-label="Model for ${esc(F.name)}" style="margin-top:4px;width:auto;padding:4px 32px 4px 8px;font-size:12px">
        ${Object.entries(AI_MODELS).map(([id, m]) => `<option value="${id}"${aiModelFor(F.id) === id ? ' selected' : ''}>${esc(m.short)}${id === AI_MODEL ? ' (default)' : ''}</option>`).join('')}</select></div>
      <span class="chip${st === 'on' ? ' green' : ''}">${word[st]}</span></div>`).join('')}
    <div class="sub" style="margin-top:8px">Per million tokens in / out: ${Object.values(AI_MODELS).map(m => `${esc(m.short)} $${m.in.toFixed(2)} / $${m.out.toFixed(2)}`).join(' · ')}. Bigger models read messy input better and cost more; Haiku is plenty for most of this.</div>
  </div>`;
}
export function wireAiUsage(bg) {
  bg.querySelectorAll('[data-aimodel]').forEach(s => s.onchange = () => {
    S.settings.aiModels = { ...(S.settings.aiModels || {}), [s.dataset.aimodel]: s.value };
    if (s.value === AI_MODEL) delete S.settings.aiModels[s.dataset.aimodel];
    save();
    $('#stAiUse', bg).innerHTML = aiUsageHtml(); wireAiUsage(bg);
  });
  const r = $('#stAiReset', bg);
  if (r) r.onclick = () => confirmDlg('Reset this month\'s AI count? Only the count — nothing is refunded.', () => {
    aiSaveUsage({ month: aiMonth(), calls: 0, inTok: 0, outTok: 0, usd: 0, by: {} });
    $('#stAiUse', bg).innerHTML = aiUsageHtml(); wireAiUsage(bg);
  }, 'Reset');
}
export function aiKey() { try { return localStorage.getItem('ironlog.anthropicKey') || ''; } catch (e) { return ''; } }
export function setAiKey(k) {
  try { k ? localStorage.setItem('ironlog.anthropicKey', k) : localStorage.removeItem('ironlog.anthropicKey'); }
  catch (e) { /* private mode: no key, so the local parser is all there is */ }
}
/* A JSON reply through aiCall. Haiku usually returns bare JSON, but
   occasionally tops it with a sentence: salvage the object or array rather
   than throwing the whole reply away. */
export async function claudeParse(text, system, feature) {
  const { text: out } = await aiCall({ feature, system, user: text });
  let clean = out.replace(/```json|```/g, '').trim();
  if (clean[0] !== '[' && clean[0] !== '{') {
    const a = clean.search(/[[{]/), z = Math.max(clean.lastIndexOf(']'), clean.lastIndexOf('}'));
    if (a !== -1 && z > a) clean = clean.slice(a, z + 1);
  }
  try {
    return JSON.parse(clean);
  } catch (pe) {
    const err = new Error('badjson');
    err.badjson = true;
    err.raw = (out || '(empty reply)').slice(0, 160);
    throw err;
  }
}
